window.docContents[24].resolve({"/References/#Type-Systems--References___-Typing-Mutable-References--Properties":{"contents":"Our final task is to check that standard type safety\nproperties continue to hold for the STLC with references.  The\nprogress theorem (\"well-typed terms are not stuck\") can be stated\nand proved almost as for the STLC; we just need to add a few\nstraightforward cases to the proof to deal with the new\nconstructs.  The preservation theorem is a bit more interesting,\nso let's look at it first.\n\n\n\n\n\n\n\n\n\n\n\n","context":"Type Systems\u0009References: Typing Mutable References","header":"9.5. Properties","id":"/References/#Type-Systems--References___-Typing-Mutable-References--Properties"}});